const { chromium, devices, expect } = require('/home/gabrielhansmann/Documents/hackathons/attention_is_all_we_have/frontend/node_modules/@playwright/test');

(async () => {
  const url = process.env.ATTENTION_DEPLOY_URL;
  if (!url) throw new Error('Deployment URL is required');
  const browser = await chromium.launch({ headless: true });
  try {
    for (const [name, options] of [['desktop', { viewport: { width: 1440, height: 1000 } }], ['mobile', devices['iPhone 13']]]) {
      const context = await browser.newContext(options);
      const page = await context.newPage();
      const errors = [];
      page.on('pageerror', error => errors.push(error.message));
      page.on('console', message => { if (message.type() === 'error') errors.push(message.text()); });
      page.on('response', response => { if (response.status() >= 400) errors.push(`${response.status()} ${response.url()}`); });
      const response = await page.goto(url, { waitUntil: 'networkidle' });
      expect(response.status()).toBe(200);
      expect(response.headers()['x-content-type-options']).toBe('nosniff');
      await expect(page.getByRole('heading', { name: 'Build what comes next.' })).toBeVisible();
      for (const [label, heading] of [['Requirements', 'Evidence into action.'], ['Research', 'Ask. Review. Decide.'], ['Evidence library', 'A source for every decision.'], ['Reports', 'A programme worth sharing.'], ['Overview', 'Build what comes next.']]) {
        if (name === 'mobile') await page.getByRole('button', { name: 'Open navigation' }).click();
        await page.getByRole('link', { name: label, exact: true }).click();
        await expect(page.getByRole('heading', { name: heading, exact: true })).toBeVisible();
        expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true);
      }
      await page.getByRole('button', { name: 'Edit Electric range (WLTP) target' }).click();
      await page.getByLabel('Successor target (km)', { exact: true }).fill('590');
      await page.getByLabel('Reason for the target').fill('Verify that the deployed workspace saves a reviewed target.');
      await page.getByRole('button', { name: 'Save target', exact: true }).click();
      await page.reload({ waitUntil: 'networkidle' });
      await expect(page.getByRole('button', { name: 'Edit Electric range (WLTP) target' })).toContainText('590');
      await page.screenshot({ path: `/tmp/attention-production-${name}.png`, fullPage: true });
      expect(errors).toEqual([]);
      console.log(`${name}: public HTTP 200, all five views, responsive layout, persisted target, no browser errors`);
      await context.close();
    }
  } finally {
    await browser.close();
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

